package claudecode

import (
	"context"
	"io"
	"os"
	"os/exec"
	"time"

	"github.com/KogenAI/kogen-loop/sys"
)

const retryLogin = "; run `kogen provider login claude-code` to retry"

// SetupToken installs the pinned runtime when it is missing and runs its `setup-token` sign-in
// on the caller's terminal; it returns the printed token, which never reaches out.
func SetupToken(ctx context.Context, home string, out io.Writer) (string, error) {
	w := &lockedWriter{w: out}
	a := New(Options{Home: home, Stderr: w}).(*adapter)
	if err := a.ensureRuntime(ctx); err != nil {
		detail := err.Error()
		if e, ok := sys.AsError(err); ok {
			detail = e.Detail
		}
		return "", unavailable("cannot install Kogen's Claude Code: " + detail + retryLogin)
	}
	cmd := exec.CommandContext(ctx, RuntimePath(home), "setup-token")
	cmd.Env = a.childEnv("", "")
	cmd.Stdin = os.Stdin
	stdout := &withholder{w: w}
	cmd.Stdout, cmd.Stderr = stdout, w
	cmd.WaitDelay = 2 * time.Second
	if err := cmd.Run(); err != nil {
		return "", unavailable("Kogen's Claude Code `setup-token` failed: " + err.Error() + retryLogin)
	}
	token := parseToken(stdout.all.String())
	if token == "" {
		return "", unavailable("Kogen's Claude Code `setup-token` printed no token" + retryLogin)
	}
	return token, nil
}

