package claudecode

import (
	"regexp"
	"strings"
)

var (
	escapeSeq = regexp.MustCompile(`\x1b\[[0-?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)`)
	tokenText = regexp.MustCompile(`^[A-Za-z0-9_-]+$`)
)

// parseToken joins the lines after the marker line up to a blank or "Store this token
// securely" line; "" when that is not one word of token text.
func parseToken(stdout string) string {
	lines := strings.Split(strings.ReplaceAll(escapeSeq.ReplaceAllString(stdout, ""), "\r", ""), "\n")
	for i, line := range lines {
		if !strings.Contains(line, tokenMarker) {
			continue
		}
		var token strings.Builder
		j := i + 1
		for j < len(lines) && strings.TrimSpace(lines[j]) == "" {
			j++
		}
		for ; j < len(lines); j++ {
			part := strings.TrimSpace(lines[j])
			if part == "" || strings.HasPrefix(part, "Store this token securely") {
				break
			}
			token.WriteString(part)
		}
		if !tokenText.MatchString(token.String()) {
			return ""
		}
		return token.String()
	}
	return ""
}

