import (
	"bytes"
	"io"
	"strings"
	"sync"
)

const tokenMarker = "Your OAuth token"

type lockedWriter struct {
	mu sync.Mutex
	w  io.Writer
}

func (l *lockedWriter) Write(p []byte) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.w.Write(p)
}

// withholder keeps all output and passes on what precedes the marker, holding back a tail
// that could start it.
type withholder struct {
	w       io.Writer
	all     bytes.Buffer
	sent    int
	stopped bool
}

func (h *withholder) Write(p []byte) (int, error) {
	h.all.Write(p)
	if h.stopped {
		return len(p), nil
	}
	data := h.all.Bytes()
	if i := bytes.Index(data[h.sent:], []byte(tokenMarker)); i >= 0 {
		h.w.Write(data[h.sent : h.sent+i])
		h.stopped = true
		return len(p), nil
	}
	end := len(data)
	for k := min(len(tokenMarker)-1, end-h.sent); k > 0; k-- {
		if strings.HasPrefix(tokenMarker, string(data[end-k:])) {
			end -= k
			break
		}
	}
	if nl := bytes.LastIndexByte(data[h.sent:end], '\n'); nl >= 0 {
		end = h.sent + nl + 1
	} else {
		end = h.sent
	}
	if end > h.sent {
		h.w.Write(data[h.sent:end])
		h.sent = end
	}
	return len(p), nil
